// 主程序
const strategies: { id: StrategyId; name: string }[] = [
  { id: 'greedy', name: '贪婪' },
  { id: 'cautious', name: '谨慎' },
  { id: 'random', name: '随机' },
  { id: 'longhold', name: '豪赌' },
  { id: 'upgrader', name: '升级' },
  { id: 'smart', name: '智能' },
];

export function runAll(runsPerStrategy: number = N, quiet: boolean = false): StrategyResult[] {
  const allResults: StrategyResult[] = [];
  if (!quiet) console.log(`开始模拟，每种策略 ${runsPerStrategy} 局...`);

  for (const strat of strategies) {
    const runs: RunResult[] = [];
    for (let seed = 1; seed <= runsPerStrategy; seed++) {
      const run = simulateRun(strat.id, seed);
      runs.push(run);
    }
    const result = computeStrategyResult(strat.id, strat.name, runs);
    allResults.push(result);
    if (!quiet) console.log(`策略 ${strat.name} 模拟完成`);
  }
  return allResults;
}

const allResults = runAll(N);

// 确保 sim 目录存在
const simDir = path.resolve(process.cwd(), 'sim');
if (!fs.existsSync(simDir)) {
  fs.mkdirSync(simDir, { recursive: true });
}

// 写入 JSON
const output = {
  totalRunsPerStrategy: N,
  strategies: allResults,
};
const outPath = path.resolve(simDir, 'result.json');
fs.writeFileSync(outPath, JSON.stringify(output, null, 2));
console.log(`结果已写入 ${outPath}`);

// 打印表格
printResults(allResults);

