{"file_path": "/workspace/lingyuan15/sim/tune.ts", "content": "// 临时调参工具：不参与提交，调到目标后删除。
import { CONFIG, ITEMS, LOCATIONS } from '../src/core/config';
import { Game } from '../src/core/game';
import { runAll } from './simulate';

type Patch = {
  startHunger?: number;
  maxStamina?: number;
  startMood?: number;
  dailyHunger?: [number, number, number];
  phaseLootMul?: [number, number, number];
  phaseFarTravelMul?: [number, number, number];
  commonMul?: number;
  goodMul?: number;
  rareMul?: number;
  epicMul?: number;
  holdCurve?: { minSec: number; good: number; rare: number; epic: number }[];
  boxesPerLocation?: [number, number];
  bigBoxChance?: number;
  bigBoxBonusGood?: number;
  eventChancePerDig?: number;
  nightWarmthChance?: number;
  nightWarmthHunger?: number;
  lootFar?: number;
  lootNear?: number;
  label?: string;
};

const BASE_CONFIG = JSON.parse(JSON.stringify(CONFIG));
const BASE_ITEMS = ITEMS.map((i) => ({ id: i.id, price: i.price, hunger: i.hunger }));
const BASE_LOCS = LOCATIONS.map((l) => ({ id: l.id, lootRate: l.lootRate, distance: l.distance }));

// ---- 统计钩子：按地点/稀有度记录已实现收入 ----
let incomeByLoc: Record<string, number> = {};
let incomeByRarity: Record<string, number> = {};
let lostByLoc: Record<string, number> = {};

const origGoHome = Game.prototype.goHome;
Game.prototype.goHome = function (this: Game) {
  const loc = this.location;
  let recorded = false;
  if (loc) {
    const r = origGoHome.call(this);
    if (r) {
      // sellBagAndReport 已清空 bag，改为在调用前抓取
    }
    return r;
  }
  return origGoHome.call(this);
};

// 用 dig 钩子记录捡到的物品价值（不精确等于卖价，但可比较地点/稀有度）
const origDig = Game.prototype.dig;
Game.prototype.dig = function (this: Game, boxId: string, holdSec: number) {
  const loc = this.location ?? 'none';
  const bagBefore = this.bag.map((p) => p.itemId);
  const res = origDig.call(this, boxId, holdSec);
  if (res.ok) {
    for (const inst of res.items) {
      const def = ITEMS.find((i) => i.id === inst.itemId);
      if (!def) continue;
      const price = def.price;
      incomeByLoc[loc] = (incomeByLoc[loc] ?? 0) + price;
      incomeByRarity[def.rarity] = (incomeByRarity[def.rarity] ?? 0) + price;
    }
  }
  return res;
};

function resetStats() {
  incomeByLoc = {};
  incomeByRarity = {};
  lostByLoc = {};
}

function applyPatch(p: Patch) {
  // 恢复基线
  Object.assign(CONFIG, JSON.parse(JSON.stringify(BASE_CONFIG)));
  for (const it of ITEMS) {
    const b = BASE_ITEMS.find((x) => x.id === it.id)!;
    it.price = b.price;
    if (b.hunger !== undefined) it.hunger = b.hunger;
  }
  for (const loc of LOCATIONS) {
    const b = BASE_LOCS.find((x) => x.id === loc.id)!;
    loc.lootRate = b.lootRate;
  }

  if (p.startHunger != null) CONFIG.startHunger = p.startHunger;
  if (p.maxStamina != null) CONFIG.maxStamina = p.maxStamina;
  if (p.startMood != null) CONFIG.startMood = p.startMood;
  if (p.dailyHunger) for (let i = 0; i < 3; i++) CONFIG.phases[i].dailyHunger = p.dailyHunger[i];
  if (p.phaseLootMul) for (let i = 0; i < 3; i++) CONFIG.phases[i].lootMul = p.phaseLootMul[i];
  if (p.phaseFarTravelMul) for (let i = 0; i < 3; i++) CONFIG.phases[i].farTravelMul = p.phaseFarTravelMul[i];
  if (p.holdCurve) CONFIG.holdCurve = p.holdCurve;
  if (p.boxesPerLocation) CONFIG.boxesPerLocation = p.boxesPerLocation;
  if (p.bigBoxChance != null) for (const k of ['good', 'meh', 'bad'] as const) CONFIG.bigBoxChance[k] = p.bigBoxChance!;
  if (p.bigBoxBonusGood != null) CONFIG.bigBoxBonusGood = p.bigBoxBonusGood;
  if (p.eventChancePerDig != null) CONFIG.eventChancePerDig = p.eventChancePerDig;
  if (p.nightWarmthChance != null) CONFIG.nightWarmthChance = p.nightWarmthChance;
  if (p.nightWarmthHunger != null) CONFIG.nightWarmthHunger = p.nightWarmthHunger;

  if (p.commonMul || p.goodMul || p.rareMul || p.epicMul) {
    for (const it of ITEMS) {
      if (it.rarity === 'common') it.price = round2(it.price * (p.commonMul ?? 1));
      if (it.rarity === 'good') it.price = round2(it.price * (p.goodMul ?? 1));
      if (it.rarity === 'rare') it.price = round2(it.price * (p.rareMul ?? 1));
      if (it.rarity === 'epic') it.price = round2(it.price * (p.epicMul ?? 1));
    }
  }
  if (p.lootFar != null) for (const loc of LOCATIONS) if (loc.far) loc.lootRate = p.lootFar;
  if (p.lootNear != null) for (const loc of LOCATIONS) if (!loc.far) loc.lootRate = p.lootNear;
}

function round2(v: number) {
  return Math.round(v * 100) / 100;
}

function evaluate(patch: Patch, N: number) {
  applyPatch(patch);
  resetStats();
  const results = runAll(N, true);
  const by = Object.fromEntries(results.map((r) => [r.strategy, r]));
  const smart = by['smart'];
  const others = results.filter((r) => r.strategy !== 'smart');
  const avgOtherDays = others.reduce((s, r) => s + r.avgSurvivalDays, 0) / others.length;
  const minOtherDays = Math.min(...others.map((r) => r.avgSurvivalDays));
  const maxOtherDays = Math.max(...others.map((r) => r.avgSurvivalDays));
  const earlyDeaths =
    results.reduce((s, r) => s + (r.deathDist[1] ?? 0) + (r.deathDist[2] ?? 0) + (r.deathDist[3] ?? 0), 0) /
    (results.length * N);
  const avgDailyIncome = results.reduce((s, r) => s + r.avgDailyIncome, 0) / results.length;

  return {
    label: patch.label ?? '',
    smartWin: smart.winRate * 100,
    smartDays: smart.avgSurvivalDays,
    avgOtherDays,
    minOtherDays,
    maxOtherDays,
    earlyDeaths: earlyDeaths * 100,
    avgDailyIncome,
    incomeByLoc,
    incomeByRarity,
  };
}

function fmtRow(r: ReturnType<typeof evaluate>) {
  return [
    r.label.padEnd(26),
    r.smartWin.toFixed(1).padStart(7),
    r.avgOtherDays.toFixed(2).padStart(8),
    `${r.minOtherDays.toFixed(1)}-${r.maxOtherDays.toFixed(1)}`.padStart(10),
    r.earlyDeaths.toFixed(1).padStart(8),
    r.avgDailyIncome.toFixed(2).padStart(8),
  ].join('');
}

const N = parseInt(process.argv[3] || '300', 10);
const mode = process.argv[2] || 'sweep';

const header =
  'variant'.padEnd(26) + 'smart%'.padStart(7) + 'otherD'.padStart(8) + 'range'.padStart(10) + 'D1-3死%'.padStart(8) + 'inc/日'.padStart(8);
console.log(header);
console.log('-'.repeat(header.length));

const patches: Patch[] = [];
if (mode === 'sweep') {
  patches.push({ label: 'baseline' });
  for (const v of [70, 80, 90]) patches.push({ label: `startHunger ${v}`, startHunger: v });
  for (const v of [110, 120, 130, 140]) patches.push({ label: `maxStamina ${v}`, maxStamina: v });
  for (const v of [[20, 25, 40], [20, 25, 50], [25, 30, 50], [25, 30, 55]] as [number, number, number][])
    patches.push({ label: `dailyHunger ${v.join('/')}`, dailyHunger: v });
  for (const v of [1.5, 2, 2.5, 3]) patches.push({ label: `common×${v}`, commonMul: v });
  for (const v of [3, 4, 5]) patches.push({ label: `maxSta 130 + common×${v}`, maxStamina: 130, commonMul: v });
} else if (mode === 'custom') {
  // 由下面的 CUSTOM 定义
}

const CUSTOM: Patch[] = [];
if (mode === 'custom') {
  patches.push(...CUSTOM);
}

for (const p of patches) {
  try {
    const r = evaluate(p, N);
    console.log(fmtRow(r));
    if (process.env.DETAIL) {
      const locs = Object.entries(r.incomeByLoc)
        .map(([k, v]) => `${k}:${v.toFixed(0)}`)
        .join(' ');
      const rar = Object.entries(r.incomeByRarity)
        .map(([k, v]) => `${k}:${v.toFixed(0)}`)
        .join(' ');
      console.log('  收/地点 ' + locs);
      console.log('  收/稀有度 ' + rar);
    }
  } catch (e) {
    console.log(p.label, 'ERROR', (e as Error).message);
  }
}
"}

