      incomeByLoc[loc] = (incomeByLoc[loc] ?? 0) + price;
      incomeByRarity[def.rarity] = (incomeByRarity[def.rarity] ?? 0) + price;
    }
  }
  return res;
};

function resetStats() {
  incomeByLoc = {};
  incomeByRarity = {};
  lostByLoc = {};
}

function applyPatch(p: Patch) {
  // 恢复基线
  Object.assign(CONFIG, JSON.parse(JSON.stringify(BASE_CONFIG)));
  for (const it of ITEMS) {
    const b = BASE_ITEMS.find((x) => x.id === it.id)!;
    it.price = b.price;
    if (b.hunger !== undefined) it.hunger = b.hunger;
  }
  for (const loc of LOCATIONS) {
    const b = BASE_LOCS.find((x) => x.id === loc.id)!;
    loc.lootRate = b.lootRate;
  }

  if (p.startHunger != null) CONFIG.startHunger = p.startHunger;
  if (p.maxStamina != null) CONFIG.maxStamina = p.maxStamina;
  if (p.startMood != null) CONFIG.startMood = p.startMood;
  if (p.dailyHunger) for (let i = 0; i < 3; i++) CONFIG.phases[i].dailyHunger = p.dailyHunger[i];
  if (p.phaseLootMul) for (let i = 0; i < 3; i++) CONFIG.phases[i].lootMul = p.phaseLootMul[i];
  if (p.phaseFarTravelMul) for (let i = 0; i < 3; i++) CONFIG.phases[i].farTravelMul = p.phaseFarTravelMul[i];
  if (p.holdCurve) CONFIG.holdCurve = p.holdCurve;
  if (p.boxesPerLocation) CONFIG.boxesPerLocation = p.boxesPerLocation;
  if (p.bigBoxChance != null) for (const k of ['good', 'meh', 'bad'] as const) CONFIG.bigBoxChance[k] = p.bigBoxChance!;
  if (p.bigBoxBonusGood != null) CONFIG.bigBoxBonusGood = p.bigBoxBonusGood;
  if (p.eventChancePerDig != null) CONFIG.eventChancePerDig = p.eventChancePerDig;
  if (p.nightWarmthChance != null) CONFIG.nightWarmthChance = p.nightWarmthChance;
  if (p.nightWarmthHunger != null) CONFIG.nightWarmthHunger = p.nightWarmthHunger;

  if (p.commonMul || p.goodMul || p.rareMul || p.epicMul) {
    for (const it of ITEMS) {
      if (it.rarity === 'common') it.price = round2(it.price * (p.commonMul ?? 1));
      if (it.rarity === 'good') it.price = round2(it.price * (p.goodMul ?? 1));
      if (it.rarity === 'rare') it.price = round2(it.price * (p.rareMul ?? 1));
      if (it.rarity === 'epic') it.price = round2(it.price * (p.epicMul ?? 1));
    }
  }
  if (p.lootFar != null) for (const loc of LOCATIONS) if (loc.far) loc.lootRate = p.lootFar;
  if (p.lootNear != null) for (const loc of LOCATIONS) if (!loc.far) loc.lootRate = p.lootNear;
}

function round2(v: number) {
  return Math.round(v * 100) / 100;
}

function evaluate(patch: Patch, N: number) {
  applyPatch(patch);
  resetStats();
  const results = runAll(N, true);
  const by = Object.fromEntries(results.map((r) => [r.strategy, r]));
