{"content": "// 临时探针：估算各地点的期望收益与体力效率，验证远地点/长按是否有赚头。
import { CONFIG, ITEMS, LOCATIONS } from '../src/core/config';

const holdSteps = CONFIG.holdCurve;
const bigChance = CONFIG.bigBoxChance.meh; // 平签最常见
const boxes = (CONFIG.boxesPerLocation[0] + CONFIG.boxesPerLocation[1]) / 2;

function probs(hold: number, locLoot: number, big: boolean) {
  let good = 0,
    rare = 0,
    epic = 0;
  for (const st of holdSteps) if (st.minSec <= hold) {
    good = st.good;
    rare = st.rare;
    epic = st.epic;
  }
  const mul = locLoot;
  good = Math.min(1, good * mul + (big ? CONFIG.bigBoxBonusGood : 0));
  rare = Math.min(1, rare * mul);
  epic = Math.min(1, epic * mul);
  return { good, rare, epic, common: Math.max(0, 1 - good - rare - epic) };
}

function avgPrice(rarity: string, locId: string) {
  const cands = ITEMS.filter((i) => i.rarity === rarity);
  let total = 0,
    wsum = 0;
  for (const it of cands) {
    const w = it.locations?.includes(locId) ? 3 : 1;
    total += it.price * w;
    wsum += w;
  }
  return wsum ? total / wsum : 0;
}

function evBox(hold: number, locId: string, big: boolean) {
  const loc = LOCATIONS.find((l) => l.id === locId)!;
  const p = probs(hold, loc.lootRate, big);
  const common = avgPrice('common', locId);
  const good = avgPrice('good', locId);
  const rare = avgPrice('rare', locId);
  const epic = avgPrice('epic', locId);
  const perItem = p.common * common + p.good * good + p.rare * rare + p.epic * epic;
  const n = big ? (CONFIG.itemsPerBox.big[0] + CONFIG.itemsPerBox.big[1]) / 2 : CONFIG.itemsPerBox.small[0];
  return perItem * n;
}

function trip(hold: number, locId: string) {
  const loc = LOCATIONS.find((l) => l.id === locId)!;
  const evSmall = evBox(hold, locId, false);
  const evBig = evBox(hold, locId, true);
  const value = boxes * ((1 - bigChance) * evSmall + bigChance * evBig);
  const digSta = boxes * ((1 - bigChance) * (CONFIG.digStamina.small + hold * CONFIG.holdStaminaPerSec) + bigChance * (CONFIG.digStamina.big + hold * CONFIG.holdStaminaPerSec));
  const travel = 2 * Math.max(5, loc.distance);
  return { value, stamina: travel + digSta, ratio: value / (travel + digSta) };
}

console.log('地点           距离 爆率  3.5s/趟期望¥  体力/趟  ¥每体力   5s/趟期望¥  ¥每体力');
for (const loc of LOCATIONS) {
  const t35 = trip(3.5, loc.id);
  const t5 = trip(5, loc.id);
  console.log(
    `${loc.name.padEnd(8)} d${String(loc.distance).padStart(2)} ${loc.lootRate.toFixed(2)}  ${t35.value.toFixed(1).padStart(10)}  ${t35.stamina.toFixed(0).padStart(6)}  ${t35.ratio.toFixed(3).padStart(7)}  ${t5.value.toFixed(1).padStart(9)}  ${t5.ratio.toFixed(3).padStart(7)}`,
  );
}

console.log('\n长按每多 2 秒的边际收益（同地点、同一趟、扣翻车风险前）：');
for (const loc of LOCATIONS) {
  const a = trip(3, loc.id);
  const b = trip(5, loc.id);
  console.log(
    `${loc.name.padEnd(8)} +¥${(b.value - a.value).toFixed(2).padStart(7)}  +${(b.stamina - a.stamina).toFixed(0)} 体力  => 每体力 +¥${((b.value - a.value) / Math.max(1e-9, b.stamina - a.stamina)).toFixed(3)}`,
  );
}
