Now UI layer helper & safe layout. Create `cocos/assets/scripts/ui/UI.ts`.

Need to know imports available: `Layers`, `Widget`, `view`, `sys`, `UITransform`, `Node`. `sys.getSafeAreaRect()` returns Rect. `view.getFrameSize()`. Use try/catch.

Implementation:

```ts
import { Layers, Node, UITransform, Widget, view, sys } from 'cc';

export function uiNode(name = 'node'): Node {
  const node = new Node(name);
  node.layer = Layers.Enum.UI_2D;
  return node;
}

export class UILayout {
  static visibleW = 720;
  static visibleH = 1280;
  static safeTop = 0;
  static safeBottom = 0;
  static safeLeft = 0;
  static safeRight = 0;

  static refresh(): void {
    const vs = view.getVisibleSize();
    const frame = view.getFrameSize();
    this.visibleW = vs.width > 0 ? Math.min(720, vs.width) : 720;
    this.visibleH = vs.height > 0 ? Math.min(1280, vs.height) : 1280;
    this.safeTop = 0; ...
    try {
      const safe = sys.getSafeAreaRect();
      if (safe && frame.width > 0 && frame.height > 0) {
        const sx = vs.width / frame.width;
        const sy = vs.height / frame.height;
        this.safeTop = Math.max(0, frame.height - safe.y - safe.height) * sy;
        this.safeBottom = Math.max(0, safe.y) * sy;
        this.safeLeft = Math.max(0, safe.x) * sx;
        this.safeRight = Math.max(0, frame.width - safe.x - safe.width) * sx;
      }
    } catch {}
  }

  static get halfW(): number { return Math.min(360, this.visibleW / 2); }
  static get top(): number { return this.visibleH / 2 - this.safeTop; }
  static get bottom(): number { return -this.visibleH / 2 + this.safeBottom; }
}

export function alignBottom(node: Node, margin = 20): void {
  const w = node.getComponent(Widget) ?? node.addComponent(Widget);
  w.isAlignBottom = true;
  w.bottom = UILayout.safeBottom + margin;
  w.alignMode = Widget.AlignMode.ON_WINDOW_RESIZE;
  w.updateAlignment();
}

export function alignTop(node: Node, margin = 20, hCenter = 0): void { ... }
```
Widget align mode: `ON_WINDOW_RESIZE` maybe means only on resize; default `ON_WINDOW_RESIZE`. For initial, call updateAlignment. Fine.

`alignTopCenter` for labels.

But for HUD, labels are created with `createLabel` which adds to hudRoot and sets position. We can add Widget after. `Widget` with top and horizontalCenter; width/height set. Widget will position. Use:
```
const w = node.addComponent(Widget);
w.isAlignTop = true; w.top = UILayout.safeTop + 8;
w.isAlignHorizontalCenter = true; w.horizontalCenter = offset;
w.updateAlignment();
