    }

    try {
      const safe = sys.getSafeAreaRect();
      if (safe && frameW > 0 && frameH > 0) {
        const sx = vsW / frameW;
        const sy = vsH / frameH;
        this.safeTop = Math.max(0, frameH - safe.y - safe.height) * sy;
        this.safeBottom = Math.max(0, safe.y) * sy;
        this.safeLeft = Math.max(0, safe.x) * sx;
        this.safeRight = Math.max(0, frameW - safe.x - safe.width) * sx;
      }
    } catch (e) {
      // 忽略，按 0 安全区处理
    }
  }

