{"command": "cd /workspace/lingyuan15 && python3 - <<'EOF'
p='cocos/assets/scripts/ui/UI.ts'
s=open(p).read()
old="""    let vsW = 720;
    let vsH = 1280;
    let frameW = 720;
    let frameH = 1280;
    try {
      const vs = view.getVisibleSize();
      const frame = view.getFrameSize();
      if (vs && vs.width > 0 && vs.height > 0) {
        vsW = Math.min(720, vs.width);
        vsH = Math.min(1280, vs.height);
      }
      if (frame && frame.width > 0 && frame.height > 0) {
        frameW = frame.width;
        frameH = frame.height;
      }
      this.visibleW = vsW;
      this.visibleH = vsH;
    } catch (e) {
      // 非运行环境（如 tsc/单测）使用设计分辨率
    }"""
new="""    let vsW = 720;
    let vsH = 1280;
    let frameW = 720;
    let frameH = 1280;
    try {
      const vs = view.getVisibleSize();
      const frame = view.getFrameSize();
      if (vs && vs.width > 0 && vs.height > 0) {
        vsW = Math.min(720, vs.width);
        vsH = Math.min(1280, vs.height);
      }
      if (frame && frame.width > 0 && frame.height > 0) {
        frameW = frame.width;
        frameH = frame.height;
        // 项目设置为 720×1280 + Fit Height：
        // 实际可视宽度 = 屏幕宽 × 设计高 / 屏幕高，两侧会被裁掉
        const fitScale = frameH / 1280;
        if (fitScale > 0) {
          vsW = Math.min(720, frameW / fitScale);
          vsH = 1280;
        }
      }
      this.visibleW = vsW;
      this.visibleH = vsH;
    } catch (e) {
      // 非运行环境（如 tsc/单测）使用设计分辨率
    }"""
assert old in s
s=s.replace(old,new,1)
open(p,'w').write(s)
print('visible width from fit-height')
EOF
npx tsc -p cocos/tsconfig.check.json 2>&1 | head; echo "exit=${PIPESTATUS[0]}"", "description": "Derive visible width from fit-height frame", "timeoutMs": 300000}

