    const w = stage.getComponent(UITransform)!.width;
    const h = stage.getComponent(UITransform)!.height;
    switch (ev.id) {
      case 'patrol': {
        if (optionIndex === 0) {
          const hero = stage.getChildByName('hero') || this.block(stage, 'hero', 80, 120, new Color(90, 170, 255, 255), 0, -160);
          tween(hero).to(0.4, { scale: new Vec3(1, 0.7, 1) }).to(0.4, { scale: Vec3.ONE }).call(() => {
            tween(hero).to(0.8, { position: new Vec3(-w / 2 - 100, -160, 0) }).start();
          }).start();
          this.label(stage, '礼貌离开', 28, 0, 80);
          await Fx.freeze(1.2);
        } else {
          const hero = stage.getChildByName('hero') || this.block(stage, 'hero', 80, 120, new Color(90, 170, 255, 255), -120, -160);
          const npc = stage.getChildByName('rivalNpc') || this.block(stage, 'npc', 90, 130, new Color(255, 110, 110, 255), 180, -160);
          const success = Math.random() < 0.5;
          if (success) {
            tween(hero).by(0.3, { position: new Vec3(60, 0, 0) }).by(0.3, { position: new Vec3(-60, 0, 0) }).start();
            await Fx.freeze(0.7);
            tween(npc).to(0.7, { position: new Vec3(w / 2 + 200, -160, 0) }).start();
            this.label(stage, '大叔挥手走', 28, 0, 80);
          } else {
            tween(hero).by(0.3, { position: new Vec3(60, 0, 0) }).by(0.3, { position: new Vec3(-60, 0, 0) }).start();
            await Fx.freeze(0.7);
            this.label(stage, '这边请~', 30, 0, 80);
          }
          await Fx.freeze(1.0);
        }
        break;
      }
      case 'guard': {
        this.label(stage, '被赶走了', 28, 0, -180);
        await Fx.freeze(1.0);
        break;
      }
      case 'rival': {
        if (optionIndex === 0) {
          this.label(stage, '你认怂了', 28, 0, 80);
          await Fx.freeze(1.0);
        } else {
          if (minigameWin) {
            const rival = stage.getChildByName('rivalNpc') || this.block(stage, 'rivalNpc', 90, 130, new Color(255, 110, 110, 255), 180, -160);
            tween(rival).to(0.7, { position: new Vec3(w / 2 + 200, -160, 0) }).start();
            this.label(stage, '对方耸肩离开', 28, 0, 80);
            await Fx.freeze(0.9);
          } else {
            const hero = stage.getChildByName('player') || this.block(stage, 'player', 90, 130, new Color(90, 170, 255, 255), -180, -160);
            tween(hero).to(0.4, { scale: new Vec3(1, 0.4, 1) }).start();
            this.label(stage, '被压扁了', 28, 0, 80);
            await Fx.freeze(1.0);
          }
        }
        break;
      }
      case 'auntie': {
        this.label(stage, '饱腹 + 心情 +', 28, 0, 80);
        await Fx.freeze(1.0);
        break;
      }
      case 'delivery': {
