{"command": "cd /workspace/lingyuan15 && python3 - <<'EOF'
p='cocos/assets/scripts/ui/EventView.ts'
s=open(p).read()
old="""    const frames = Art.frames(`ev_${ev.id}`);
    if (frames.length > 0) {
      const vis = Art.makeVisual(`ev_${ev.id}`, stage.getComponent(UITransform)!.width, stage.getComponent(UITransform)!.height, COLORS[ev.id] || Color.WHITE, ev.name);
      vis.parent = stage;
      await Fx.freeze(1.5);
      return;
    }"""
new="""    const frames = Art.frames(`ev_${ev.id}`);
    if (frames.length > 0) {
      const stageUt = stage.getComponent(UITransform)!;
      const frame = frames[0];
      const fw = Math.max(1, frame.originalSize.width);
      const fh = Math.max(1, frame.originalSize.height);
      // 固定尺寸 + 整数倍放大，居中显示，禁止把 NPC 像素图拉满全屏
      const maxSide = Math.min(stageUt.width * 0.55, stageUt.height * 0.4, 256);
      const scale = Math.max(1, Math.floor(Math.min(maxSide / fw, maxSide / fh)));
      const visW = fw * scale;
      const visH = fh * scale;
      const vis = Art.makeVisual(`ev_${ev.id}`, visW, visH, COLORS[ev.id] || Color.WHITE);
      vis.parent = stage;
      vis.setPosition(0, 70, 0);
      this.label(stage, ev.name, 30, 0, 70 - visH / 2 - 34);
      await Fx.freeze(1.5);
      return;
    }"""
assert old in s
s=s.replace(old,new,1)

old2="""    const g = n.addComponent(Graphics);
    g.fillColor = new Color(40, 40, 48, 230);
    g.rect(-w / 2, -h / 2, w, h);
    g.fill();
    g.lineWidth = 2;
    g.strokeColor = new Color(200, 200, 220, 200);
    g.stroke();"""
new2="""    const g = n.addComponent(Graphics);
    // 选项按钮：不透明深底 + 高对比亮边，避免和事件背景糊在一起
    g.fillColor = new Color(22, 24, 32, 255);
    g.rect(-w / 2, -h / 2, w, h);
    g.fill();
    g.lineWidth = 3;
    g.strokeColor = new Color(255, 214, 110, 255);
    g.stroke();
    g.strokeColor = new Color(255, 255, 255, 80);
    g.rect(-w / 2 + 4, -h / 2 + 4, w - 8, h - 8);
    g.stroke();"""
assert old2 in s
s=s.replace(old2,new2,1)
open(p,'w').write(s)
print('event NPC sizing + option buttons')
EOF
npx tsc -p cocos/tsconfig.check.json 2>&1 | head -20; echo "exit=${PIPESTATUS[0]}"", "description": "Fix NPC scaling and event option contrast", "timeoutMs": 300000}

