{"command": "cd /workspace/lingyuan15 && python3 - <<'EOF'
points={'university_town':(210,154),'huaqiangbei':(301,216),'nanshan_tech':(43,264),'baishizhou':(178,301),'window_world':(106,311),'dongmen':(329,357),'futian_cbd':(244,403),'sz_bay':(59,421)}
btnW,btnH=140,68
for visW in [520,540,560,592,640,720]:
    scaleX=min(1,(visW-48)/720); halfW=visW/2; safeX=max(80,halfW-btnW/2-4)
    raw=[]
    for k,(x,y) in points.items():
        cx=max(-safeX,min(safeX,(x-180)*2*scaleX)); cy=(320-y)*2
        raw.append((k,cx,cy))
    raw.sort(key=lambda t:-t[2])
    placed=[]; out={}
