  g.phase = 'location';
  g.location = 'baishizhou';
  g.stamina = 50;
  g.bag = [
    { uid: 1, itemId: 'old_newspaper', x: 0, y: 0, w: 1, h: 1 },
    { uid: 2, itemId: 'old_phone', x: 1, y: 0, w: 1, h: 1 },
