{"command": "cd /workspace/lingyuan15 && python3 - <<'EOF'
p='cocos/assets/scripts/ui/LocationView.ts'
s=open(p).read()
s=s.replace("const CELL = 80;\nconst SMALL_BOX", "const CELL = 80;\n// 物品图标 80 = 16px 原图 ×5，至少是旧 48px 的 1.5 倍，且正好放进一格\nconst ITEM_SIZE = 80;\nconst ITEM_PLATE = 76;\nconst SMALL_BOX")
old="""  private createItemNode(item: ItemInst, def?: ItemDef, color?: Color): Node {
    const fallbackColor = color ?? this.rarityColor(def?.rarity ?? 'common');
    const node = Art.makeVisual(`icon_${item.itemId}`, 48, 48, fallbackColor, def?.name ?? item.itemId);
    // 代码建出来的节点在部分平台锚点不是 (0.5,0.5)，显式设成中心锚点
    const ut = node.getComponent(UITransform);
    if (ut) ut.setAnchorPoint(0.5, 0.5);
    return node;
  }"""
new="""  private createItemNode(item: ItemInst, def?: ItemDef, color?: Color): Node {
    const fallbackColor = color ?? this.rarityColor(def?.rarity ?? 'common');
    // 容器负责 80×80 的命中/摆放；深色圆角底板垫在图标下面
    const root = uiNode(`item_${item.itemId}`);
    const rut = root.addComponent(UITransform);
    rut.setContentSize(ITEM_SIZE, ITEM_SIZE);
    rut.setAnchorPoint(0.5, 0.5);
    const g = root.addComponent(Graphics);
    g.fillColor = new Color(18, 20, 26, 178); // ~70% 不透明
    g.roundRect(-ITEM_PLATE / 2, -ITEM_PLATE / 2, ITEM_PLATE, ITEM_PLATE, 10);
    g.fill();
    g.lineWidth = 2;
    g.strokeColor = new Color(255, 255, 255, 45);
    g.roundRect(-ITEM_PLATE / 2, -ITEM_PLATE / 2, ITEM_PLATE, ITEM_PLATE, 10);
    g.stroke();

    const icon = Art.makeVisual(
      `icon_${item.itemId}`,
      ITEM_SIZE,
      ITEM_SIZE,
      fallbackColor,
      def?.name ?? item.itemId,
    );
    icon.parent = root;
    icon.setPosition(0, 0, 0);
    const iut = icon.getComponent(UITransform);
    if (iut) iut.setAnchorPoint(0.5, 0.5);
    return root;
  }"""
assert old in s
s=s.replace(old,new,1)
old2="""  private getFloorSlotPosition(index: number): Vec3 {
    const n = Math.max(1, this.game.floor.length);
    const perRow = 6;
    const row = Math.floor(index / perRow);
    const col = index % perRow;
    const inRow = Math.min(perRow, Math.max(1, n - row * perRow));
    const safeW = Math.min(720, UILayout.visibleW) - 56;
    const spacing = Math.max(44, Math.min(70, safeW / Math.max(1, inRow)));
    const x = (col - (inRow - 1) / 2) * spacing;
    return new Vec3(x, 40 - row * 72, 0);
  }"""
new2="""  private getFloorSlotPosition(index: number): Vec3 {
    const n = Math.max(1, this.game.floor.length);
    const perRow = 6;
    const row = Math.floor(index / perRow);
    const col = index % perRow;
    const inRow = Math.min(perRow, Math.max(1, n - row * perRow));
    const safeW = Math.min(720, UILayout.visibleW) - 56;
    // 图标加大到 80 后，间距至少 84，避免相邻物品叠在一起
    const spacing = Math.max(84, Math.min(96, safeW / Math.max(1, inRow)));
    const x = (col - (inRow - 1) / 2) * spacing;
    return new Vec3(x, 50 - row * 84, 0);
  }"""
assert old2 in s
s=s.replace(old2,new2,1)
# move hint above floor row
s=s.replace("hint.setPosition(0, -127, 0);", "hint.setPosition(0, 42, 0);")
open(p,'w').write(s)
print('item icons enlarged with plate; floor spacing updated')
EOF
