{"command": "cd /workspace/lingyuan15 && python3 - <<'EOF'
p='cocos/assets/scripts/ui/LocationView.ts'
s=open(p).read()
s=s.replace("""const CELL = 80;
// 物品图标 80 = 16px 原图 ×5，至少是旧 48px 的 1.5 倍，且正好放进一格
const ITEM_SIZE = 80;
const ITEM_PLATE = 76;
const SMALL_BOX""","""const CELL = 80;
// 地面战利品 48 = 16px 原图 ×3；背包 32 = ×2
const FLOOR_ICON = 48;
const FLOOR_PLATE = 56;
const FLOOR_GLOW = 64;
const BAG_ICON = 32;
const BAG_PLATE = 40;
const SMALL_BOX""")
old="""  private createItemNode(item: ItemInst, def?: ItemDef, color?: Color): Node {
    const fallbackColor = color ?? this.rarityColor(def?.rarity ?? 'common');
    // 容器负责 80×80 的命中/摆放；深色圆角底板垫在图标下面
    const root = uiNode(`item_${item.itemId}`);
    const rut = root.addComponent(UITransform);
    rut.setContentSize(ITEM_SIZE, ITEM_SIZE);
    rut.setAnchorPoint(0.5, 0.5);
    const g = root.addComponent(Graphics);
    g.fillColor = new Color(18, 20, 26, 178); // ~70% 不透明
    g.roundRect(-ITEM_PLATE / 2, -ITEM_PLATE / 2, ITEM_PLATE, ITEM_PLATE, 10);
    g.fill();
    g.lineWidth = 2;
    g.strokeColor = new Color(255, 255, 255, 45);
    g.roundRect(-ITEM_PLATE / 2, -ITEM_PLATE / 2, ITEM_PLATE, ITEM_PLATE, 10);
    g.stroke();

    const icon = Art.makeVisual(
      `icon_${item.itemId}`,
      ITEM_SIZE,
      ITEM_SIZE,
      fallbackColor,
      def?.name ?? item.itemId,
    );
    icon.parent = root;
    icon.setPosition(0, 0, 0);
    const iut = icon.getComponent(UITransform);
    if (iut) iut.setAnchorPoint(0.5, 0.5);
    return root;
  }"""
new="""  private createItemNode(
    item: ItemInst,
    def?: ItemDef,
    color?: Color,
    context: 'floor' | 'bag' = 'floor',
  ): Node {
    const fallbackColor = color ?? this.rarityColor(def?.rarity ?? 'common');
    const isFloor = context === 'floor';
    const iconSize = isFloor ? FLOOR_ICON : BAG_ICON;
    const plateSize = isFloor ? FLOOR_PLATE : BAG_PLATE;
    const rarity = def?.rarity ?? 'common';

    const root = uiNode(`item_${item.itemId}`);
    const rut = root.addComponent(UITransform);
    rut.setContentSize(plateSize, plateSize);
    rut.setAnchorPoint(0.5, 0.5);
    // 透明命中层：保证容器本身可接收触摸
    const hit = root.addComponent(Graphics);
    hit.fillColor = new Color(0, 0, 0, 1);
    hit.rect(-plateSize / 2, -plateSize / 2, plateSize, plateSize);
    hit.fill();

    if (isFloor) {
      // 外围稀有度色光环，复用 fx/glow_* 序列帧
      const glowInfo = this.rarityGlow(rarity);
      const glow = Art.makeVisual(glowInfo.name, FLOOR_GLOW, FLOOR_GLOW, glowInfo.color);
      glow.parent = root;
      glow.setPosition(0, 0, 0);
      const gsp = glow.getComponent(Sprite);
      if (gsp) gsp.color = glowInfo.color;
      const gop = glow.getComponent(UIOpacity) ?? glow.addComponent(UIOpacity);
      gop.opacity = 220;
    }

    // #000 alpha 0.55 的圆角底板
    const plate = uiNode('plate');
    plate.parent = root;
