  private boxSpacing(): { x: number; y: number } {
    // 安全区是 390/844 这类竖屏时，可视宽只有 ~592 设计单位
    const safeW = Math.min(720, UILayout.visibleW) - 40;
    const x = Math.max(120, Math.min(180, (safeW - BIG_BOX) / 2));
    return { x, y: 168 };
  }

