# add title in show after bg
old="""    this.adaptBackgroundToHeight(bg, 1280);

    // 盒子区域"""
new="""    this.adaptBackgroundToHeight(bg, 1280);

    // 地点标题固定在盒子和战利品区之间，战利品不再压住标题
    const locTitle = loc?.name ?? locId;
    const titleBg = uiNode('loc_title_bg');
    titleBg.parent = this.viewNode;
    const tbUt = titleBg.addComponent(UITransform);
    tbUt.setContentSize(380, 44);
    titleBg.setPosition(0, 110, 0);
    const tbg = titleBg.addComponent(Graphics);
    tbg.fillColor = new Color(0, 0, 0, 150);
    tbg.roundRect(-190, -22, 380, 44, 12);
    tbg.fill();
    const titleNode = uiNode('loc_title');
    titleNode.parent = this.viewNode;
    const tnUt = titleNode.addComponent(UITransform);
    tnUt.setContentSize(360, 40);
    const tnLb = titleNode.addComponent(Label);
    tnLb.string = locTitle;
    tnLb.fontSize = 26;
    tnLb.lineHeight = 30;
    tnLb.color = new Color(255, 245, 215, 255);
    tnLb.horizontalAlign = Label.HorizontalAlign.CENTER;
    tnLb.verticalAlign = Label.VerticalAlign.CENTER;
    tnLb.overflow = Label.Overflow.SHRINK;
    titleNode.setPosition(0, 110, 0);

    // 盒子区域"""
